import { HttpTypes } from "@medusajs/types"
import { NextRequest, NextResponse } from "next/server"
import redirectMap from "./content/redirects.json"
import { SERVE_BARE_PATHS } from "./lib/util/product-url"

const BACKEND_URL = process.env.MEDUSA_BACKEND_URL
const PUBLISHABLE_API_KEY = process.env.NEXT_PUBLIC_MEDUSA_PUBLISHABLE_KEY
const DEFAULT_REGION = process.env.NEXT_PUBLIC_DEFAULT_REGION || "us"

/**
 * Legacy SFCC URLs -> where they live now. Generated by scripts/build_redirects.py.
 *
 * Until this was wired up, `data/url-map.csv` was a spreadsheet and nothing served it: every
 * indexed product URL — the `.html` form in every Google result and customer bookmark —
 * returned 404 while the map claimed 1,308 rows of coverage. Browse URLs happened to work
 * because the live path and our route path are identical; products never shared that shape.
 * "Rows in a CSV" and "working redirects" are different claims, and only one was true.
 *
 * Matching is case-insensitive and trailing-slash-insensitive: SFCC slugs are not reliably
 * lowercase (`ballet-barre-long-sleeve-in-Skydive` is live), and an indexed link carries
 * whatever form was published.
 */
const LEGACY_REDIRECTS = (redirectMap as { redirects: Record<string, string> }).redirects

const legacyDestination = (pathname: string): string | undefined => {
  const key = pathname.replace(/\/+$/, "").toLowerCase() || "/"
  const destination = LEGACY_REDIRECTS[key]

  // 63 entries in the map are identity (`/account` -> `/account`, `/bells` -> `/bells`, and
  // `/` itself). They are native paths that survived the SFCC mapping unchanged, not legacy
  // URLs that moved. Redirecting them here sent them out as a PERMANENT 301 into the prefixed
  // shape, which is exactly what PERMANENT_PREFIX_REDIRECT below deliberately refuses to do
  // while the prefix is undecided -- and it did it to the homepage. Returning undefined drops
  // them through to the country-prefix handling, so every native path leaves on the same
  // temporary code and the whole site becomes permanent together when the prefix is settled.
  //
  // Case- and encoding-only differences (`%2c` -> `%2C`) are NOT identity and still redirect.
  return destination === key ? undefined : destination
}

// Marks a request as one the middleware rewrote itself. See the middleware body.
const INTERNAL_REWRITE_HEADER = "x-yd-internal-rewrite"

/**
 * Serve pages at the bare path (/shop/tops) rather than redirecting to /us/shop/tops.
 *
 * **DEFAULT ON since 2026-08-25 — Jeff's decision: drop the `/us/` prefix, "we can add it back
 * down the road."** It stays a flag rather than a restructure precisely so that adding it back
 * is one line: the app still routes through `[countryCode]` internally and this serves the bare
 * URL by REWRITING onto that tree. Set `YD_SERVE_BARE_PATHS=0` to put the prefix back.
 *
 * **The default lives in the CODE, not in `.env.local`, and that is the whole point.**
 * `storefront/.env.local` is gitignored, so while this was an opt-in flag, merging this branch
 * gave another lane the code and none of the configuration: yd-accounts merged the bare-path
 * middleware, built, and its site genuinely served `/us/` — its measurement was right and
 * described its own env file rather than the site. Nothing errors, nothing warns, and because
 * `NEXT_PUBLIC_*` is inlined at build time it also changes every URL the app EMITS, canonicals
 * included. **A behaviour that only production has is a behaviour nobody else can test.**
 */
// Imported, not re-derived: see the note beside it in product-url.ts.

/**
 * Whether the COUNTRY-PREFIX redirect is permanent (308) or temporary (307).
 *
 * Not to be confused with the legacy SFCC redirects, which are already 301 and should stay
 * that way — those are the migration-critical ones, and their destinations are stored
 * prefix-free so the prefix decision does not move them.
 *
 * It was temporary on purpose while the URL shape was undecided: a 308 is cached hard by
 * browsers and intermediaries, and a permanent redirect pointing INTO a shape we might drop
 * gets baked into caches we do not control. **The shape is now decided, so this is ON** — and
 * it now governs the redirect in the OTHER direction, `/us/shop/tops` -> `/shop/tops`, because
 * with bare paths the prefixed URL is the one that no longer exists.
 */
const PERMANENT_PREFIX_REDIRECT = process.env.YD_PERMANENT_REDIRECTS !== "0"

const regionMapCache = {
  regionMap: new Map<string, HttpTypes.StoreRegion>(),
  regionMapUpdated: Date.now(),
}

async function getRegionMap(cacheId: string) {
  const { regionMap, regionMapUpdated } = regionMapCache

  if (!BACKEND_URL) {
    throw new Error(
      "Middleware.ts: Error fetching regions. Did you set up regions in your Medusa Admin and define a MEDUSA_BACKEND_URL environment variable? Note that the variable is no longer named NEXT_PUBLIC_MEDUSA_BACKEND_URL."
    )
  }

  if (
    !regionMap.keys().next().value ||
    regionMapUpdated < Date.now() - 3600 * 1000
  ) {
    // Fetch regions from Medusa. We can't use the JS client here because middleware is running on Edge and the client needs a Node environment.
    const { regions } = await fetch(`${BACKEND_URL}/store/regions`, {
      headers: {
        "x-publishable-api-key": PUBLISHABLE_API_KEY!,
      },
      next: {
        revalidate: 3600,
        tags: [`regions-${cacheId}`],
      },
      cache: "force-cache",
    }).then(async (response) => {
      const json = await response.json()

      if (!response.ok) {
        throw new Error(json.message)
      }

      return json
    })

    if (!regions?.length) {
      throw new Error(
        "No regions found. Please set up regions in your Medusa Admin."
      )
    }

    // Create a map of country codes to regions.
    regions.forEach((region: HttpTypes.StoreRegion) => {
      region.countries?.forEach((c) => {
        regionMapCache.regionMap.set(c.iso_2 ?? "", region)
      })
    })

    regionMapCache.regionMapUpdated = Date.now()
  }

  return regionMapCache.regionMap
}

/**
 * Fetches regions from Medusa and sets the region cookie.
 * @param request
 * @param response
 */
async function getCountryCode(
  request: NextRequest,
  regionMap: Map<string, HttpTypes.StoreRegion | number>
) {
  try {
    let countryCode

    const vercelCountryCode = request.headers
      .get("x-vercel-ip-country")
      ?.toLowerCase()

    const urlCountryCode = request.nextUrl.pathname.split("/")[1]?.toLowerCase()

    if (urlCountryCode && regionMap.has(urlCountryCode)) {
      countryCode = urlCountryCode
    } else if (vercelCountryCode && regionMap.has(vercelCountryCode)) {
      countryCode = vercelCountryCode
    } else if (regionMap.has(DEFAULT_REGION)) {
      countryCode = DEFAULT_REGION
    } else if (regionMap.keys().next().value) {
      countryCode = regionMap.keys().next().value
    }

    return countryCode
  } catch (error) {
    if (process.env.NODE_ENV === "development") {
      console.error(
        "Middleware.ts: Error getting the country code. Did you set up regions in your Medusa Admin and define a MEDUSA_BACKEND_URL environment variable? Note that the variable is no longer named NEXT_PUBLIC_MEDUSA_BACKEND_URL."
      )
    }
  }
}

/**
 * Middleware: legacy redirects, then region selection.
 *
 * ORDER IN THIS FUNCTION IS LOAD-BEARING, and every fault in it this week has been an
 * ordering fault rather than a logic one — each block correct in isolation, wrong where it
 * sat:
 *
 *   - the bare-path rewrite and the prefix-strip formed an infinite loop, because a
 *     production build re-invokes middleware on a rewrite (dev does not)
 *   - the `.html` 404 guard placed above the legacy lookup 404'd every URL the redirect map
 *     exists to rescue: 0 of 25 sampled legacy URLs resolved
 *
 * The order below is deliberate. Change it only with a sample of real legacy URLs to check
 * against, and check them against a PRODUCTION BUILD — dev does not reproduce either fault:
 *
 *   1. resolve the country code (falling back if Medusa is unreachable)
 *   2. legacy SFCC URL -> 301, one hop, straight to the prefixed destination
 *   3. any other `.html` -> honest 404 (never a 200 carrying a "not found" page)
 *   4. country-prefix handling
 *   5. static assets
 */
export async function middleware(request: NextRequest) {
  // Build redirects from the PUBLIC host, never from this server's own address.
  //
  // `request.nextUrl.origin` comes from the Host header, which behind the edge proxy is the
  // internal address — so the front door was telling every visitor to go to
  // `http://localhost:8000/us`, an address that only exists on this machine. Jeff could not
  // load the site at all.
  //
  // A relative Location would be valid HTTP and is what I tried first; Next's middleware
  // rejects it with `TypeError: Invalid URL`, so it has to be absolute. The forwarded
  // headers carry the hostname the visitor actually used, which is the thing we want.
  //
  // THIRD time a public URL has been derived from the server's own address: Medusa stored
  // image URLs as localhost:9000, next/image resolved relative /static against its own
  // origin, and now this. Treat any absolute URL built from an origin as suspect.
  // Set by this middleware on a request it rewrote itself. If a production build re-enters
  // middleware on that rewrite, this is what stops the prefix-strip from undoing the rewrite.
  const isInternalRewrite = request.headers.get(INTERNAL_REWRITE_HEADER) !== null

  const forwardedHost = request.headers.get("x-forwarded-host")
  const forwardedProto = request.headers.get("x-forwarded-proto")
  // Prefer the host the CLIENT asked for over this server's own idea of its origin.
  //
  // Off the edge proxy, a request to http://127.0.0.1:8000/us/cart is redirected to
  // http://localhost:8000/cart -- a DIFFERENT ORIGIN, so the cart cookie does not travel and
  // the visitor (here, another lane's test harness) lands on an empty cart. That reads as a
  // broken checkout and is a changed hostname.
  //
  // HONEST STATE: this Host-header fallback did NOT change that behaviour when measured --
  // `Host: 127.0.0.1:8000` still redirected to localhost, and I do not yet know why, so this
  // is a correctness improvement and NOT a fix for that symptom. `x-forwarded-host` IS
  // honoured (verified: it redirects to whatever it names), which is what makes the edge work.
  // Until the 127.0.0.1 case is understood, drive this server at http://localhost:8000.
  const hostHeader = request.headers.get("host")
  const publicOrigin = forwardedHost
    ? `${forwardedProto || "https"}://${forwardedHost}`
    : hostHeader
    ? `${forwardedProto || request.nextUrl.protocol.replace(":", "")}://${hostHeader}`
    : request.nextUrl.origin

  /**
   * CLOSED, after three rounds of guessing: **the 127.0.0.1 -> localhost redirect is not ours
   * to fix, and every attempt aimed at the origin was aimed at the wrong thing.**
   *
   * Instrumented rather than reasoned about. A request to `127.0.0.1:8000/us/cart` produced:
   *
   *     host                127.0.0.1:8000
   *     x-forwarded-host    127.0.0.1:8000
   *     publicOrigin        http://127.0.0.1:8000     <- what this file computes: CORRECT
   *     Location            http://localhost:8000/cart <- what the client receives
   *
   * The origin chosen here is right. Writing the `Location` header by hand instead of using
   * `NextResponse.redirect()` changes nothing, so the rewrite happens BELOW middleware, in
   * Next's own server, against its idea of the deployment origin. `x-forwarded-host` set by an
   * external proxy IS honoured, which is why the edge works.
   *
   * **Consequence, and it has already cost a lane a run: a redirect that crosses origin drops
   * the cart cookie.** yd-pay drove this server at 127.0.0.1, got bounced to localhost, and
   * measured an empty cart with no tenders at the payment step -- indistinguishable from a
   * broken checkout. **Drive it at http://localhost:8000.**
   */
  const redirectTo = (path: string, status: 307 | 308 = 307) =>
    NextResponse.redirect(new URL(path, publicOrigin), status)

  let response = redirectTo(`${request.nextUrl.pathname}${request.nextUrl.search}`)

  let cacheIdCookie = request.cookies.get("_medusa_cache_id")

  let cacheId = cacheIdCookie?.value || crypto.randomUUID()

  // A backend outage must not make the site unreachable.
  //
  // getRegionMap fetches /store/regions from Medusa. When Medusa is down that throws, the
  // country code comes back undefined, and every branch below falls through to the initial
  // response — which is a redirect to the SAME url. The result is an infinite 307 loop on
  // every page, and a browser showing ERR_TOO_MANY_REDIRECTS. That is what took the preview
  // down when medusa.service crash-looped; the loop was blamed on a routing change, but any
  // Medusa outage produces it.
  //
  // Falling back to the default region means the site SERVES with a backend outage instead
  // of becoming unreachable. Pages that need product data will degrade on their own terms,
  // which is a much better failure than a redirect loop that looks like a routing bug.
  let regionMap: Awaited<ReturnType<typeof getRegionMap>> | null = null
  try {
    regionMap = await getRegionMap(cacheId)
  } catch (error) {
    console.error(
      "[middleware] could not load regions from Medusa; falling back to " +
        `'${DEFAULT_REGION}' so the site still serves.`,
      error
    )
  }

  const countryCode =
    (regionMap && (await getCountryCode(request, regionMap))) || DEFAULT_REGION

  /**
   * Legacy URLs first, and as a 301.
   *
   * PERMANENT on purpose: a 302/307 tells Google the OLD url is still canonical, which is the
   * exact opposite of what a migration needs — the point of this map is to move ranking to
   * the new URL. It is also sent in ONE hop, straight to the prefixed destination, rather
   * than redirecting to a bare path and letting the country-code branch redirect again;
   * every extra hop is ranking signal lost and latency added.
   */
  const legacy = legacyDestination(request.nextUrl.pathname)
  if (legacy) {
    // The country prefix is prepended ONLY while we serve prefixed URLs. With bare paths on
    // it must not be, or all 1,300 legacy URLs 301 to /us/... and the change buys nothing
    // for the URLs it matters most for. This is the one line that flips with the URL shape,
    // which is why destinations in redirects.json are stored prefix-free.
    const destination = SERVE_BARE_PATHS ? legacy : `/${countryCode}${legacy}`

    // An identity destination is not a redirect — with bare paths on, /shop/tops maps to
    // /shop/tops, and 301ing a URL to itself is a loop.
    //
    // FALL THROUGH here rather than returning: the bare-path rewrite below is what maps
    // /shop/tops onto the /us/shop/tops route tree. An early `NextResponse.next()` skipped
    // it and 404'd every identity path INCLUDING THE HOMEPAGE. All three of these faults
    // were found on a spare port; the previous attempt at this change found its faults by
    // taking the preview down.
    if (destination !== request.nextUrl.pathname) {
      const target = new URL(`${destination}${request.nextUrl.search}`, publicOrigin)
      return NextResponse.redirect(target, 301)
    }
  }

  /**
   * An unmatched `.html` path is a legacy URL we have no destination for. It must 404
   * honestly.
   *
   * Without this it fell through the static-asset check below (anything containing a dot is
   * treated as a file), Next matched the catch-all browse route, and the response was
   * **HTTP 200 carrying a "not found" page** — a soft 404. That is worse than a 404: Google
   * indexes it as a real page with thin content, so a dead product URL becomes a live low
   * quality one. `.html` is never a valid path on this storefront, so there is no case where
   * letting one through is right.
   */
  if (request.nextUrl.pathname.toLowerCase().endsWith(".html")) {
    return new NextResponse("Not found", {
      status: 404,
      headers: { "content-type": "text/plain; charset=utf-8" },
    })
  }

  // EXACT first-segment match, not `.includes()`.
  //
  // The starter tested `pathname.split("/")[1].includes(countryCode)`, so any first segment
  // CONTAINING the letters "us" counted as the country prefix: `/crushed-cherry`,
  // `/warehouse-sale` and `/star-dust` were all "already prefixed". They then fell through to
  // `NextResponse.next()`, Next matched `[countryCode]` with no further segment, and all three
  // **served the homepage with a 200** — three legacy redirect destinations quietly landing on
  // the wrong page, passing any check that looks at a status code. Verified before the fix:
  // `/crushed-cherry` titled "Yoga Democracy", `/us/crushed-cherry` titled "Crushed Cherry".
  //
  // With bare paths on it would have been worse than wrong-page: those URLs are the canonical
  // ones, so the substring match would have exempted them from the rewrite permanently.
  const firstSegment = request.nextUrl.pathname.split("/")[1]?.toLowerCase() ?? ""
  const urlHasCountryCode = Boolean(
    firstSegment &&
      (firstSegment === countryCode || regionMap?.has(firstSegment))
  )

  /**
   * Bare paths are canonical (Jeff, 2026-08-25). A URL still carrying `/us/` is redirected to
   * the bare form so exactly one URL per page serves.
   *
   * 308, not 307: the shape is now decided, and a temporary redirect here would keep telling
   * crawlers the prefixed URL is still the real one. See PERMANENT_PREFIX_REDIRECT.
   *
   * `isInternalRewrite` is the loop guard, and it is the whole reason the previous attempt at
   * this took the site down: the bare-path rewrite below sends `/shop/tops` to
   * `/us/shop/tops`, a production build re-enters middleware on its own rewrite (dev does
   * not), and this block would then strip the prefix straight back off — `/shop/tops` and
   * `/us/shop/tops` chasing each other until the browser gives up. The marker rides on the
   * REWRITTEN REQUEST's headers, which is the only place the second pass can read it; setting
   * it on the response, as the old code did, marks nothing.
   */
  if (
    SERVE_BARE_PATHS &&
    urlHasCountryCode &&
    firstSegment === DEFAULT_REGION &&
    !isInternalRewrite
  ) {
    const stripped = request.nextUrl.pathname.slice(`/${firstSegment}`.length) || "/"
    return redirectTo(
      `${stripped}${request.nextUrl.search}`,
      PERMANENT_PREFIX_REDIRECT ? 308 : 307
    )
  }

  // if one of the country codes is in the url and the cache id is set, return next
  if (urlHasCountryCode && cacheIdCookie) {
    return NextResponse.next()
  }

  // If the country code is in the URL and the cache id is not set, set the cookie AND SERVE
  // THE PAGE in the same response.
  //
  // The starter redirected to the same URL here (307 -> itself), relying on the client to
  // come back carrying the cookie. Browsers do, so nothing looks wrong. Anything that does
  // not retain cookies sees an endless redirect chain on EVERY url of the site — `curl -L`
  // gives up after 50 hops. Googlebot is documented as generally not retaining cookies
  // between requests, and an endless redirect chain is the signature that gets pages dropped
  // from an index. On a replatform whose whole point is preserving URL equity, that is the
  // most expensive possible way to be quietly wrong.
  //
  // Found by yd-features' reachability check, which tests what a client without a browser's
  // conveniences actually receives.
  if (urlHasCountryCode && !cacheIdCookie) {
    const served = NextResponse.next()
    served.cookies.set("_medusa_cache_id", cacheId, {
      maxAge: 60 * 60 * 24,
    })

    return served
  }

  // check if the url is a static asset
  if (request.nextUrl.pathname.includes(".")) {
    return NextResponse.next()
  }

  const redirectPath =
    request.nextUrl.pathname === "/" ? "" : request.nextUrl.pathname

  const queryString = request.nextUrl.search ? request.nextUrl.search : ""

  /**
   * EXPERIMENT (yd-cat, 2026-08-23) — serve the bare path instead of redirecting to /us.
   *
   * The live site has no country segment: yogademocracy.com/shop/tops/. Every indexed URL,
   * back-link and bookmark is that shape, and so is every destination in the redirect map.
   * Redirecting them all to /us/… costs a hop on every entry and, as a 307, tells Google the
   * bare URL is canonical while only the prefixed one serves — the wrong signal both ways.
   *
   * REWRITE, not redirect: the request is served internally from the country-prefixed route
   * tree while the browser's URL stays bare. Nothing about the route structure changes, so
   * this is reversible in one line. A rewrite does not re-enter middleware in Next 15, so it
   * cannot loop the way the previous attempt did.
   */
  if (!urlHasCountryCode && countryCode && SERVE_BARE_PATHS) {
    // The marker goes on the REQUEST, not the response: if middleware runs again on the
    // rewritten `/us/...` request, this header is how it knows not to strip the prefix back
    // off. See the loop guard above.
    const rewrittenHeaders = new Headers(request.headers)
    rewrittenHeaders.set(INTERNAL_REWRITE_HEADER, `${countryCode}`)
    // CLONE the incoming URL and change only the pathname. Do NOT build one from
    // `request.nextUrl.origin`.
    //
    // **This took the whole public preview down and :8000 stayed green throughout.** Behind
    // Caddy every request carries `X-Forwarded-Proto: https`, and Next then reports
    // `nextUrl.origin` as `https://localhost:8000`. The rewrite target became an ABSOLUTE URL
    // whose origin differs from the server's real one, so Next stopped treating it as an
    // internal rewrite and PROXIED to it over TLS -- to a plain-HTTP port:
    //
    //     Failed to proxy https://localhost:8000/us/shop/bottoms
    //     write EPROTO ... SSL routines:tls_validate_record_header:wrong version number
    //
    // The page began streaming and then died mid-render, which is why it looked like a
    // routing miss rather than a fetch. Reproduce with one header:
    //     curl -H 'X-Forwarded-Proto: https' http://127.0.0.1:8000/   -> 500
    //     curl                                http://127.0.0.1:8000/   -> 200
    // **Every check any of us ran hit :8000 without that header**, which is why this survived
    // days of green sweeps. (Isolated to the single header by the operations agent.)
    const target = request.nextUrl.clone()
    target.pathname = `/${countryCode}${redirectPath}`
    // ...and force the scheme back to the one this server actually speaks. Cloning alone is
    // NOT enough: the clone inherits the forwarded `https`, Next compares the rewrite target
    // against the real server origin, sees a different one, and proxies to it over TLS.
    // `next start` here serves plain HTTP on 127.0.0.1:8000, so the internal target must say
    // http. The public URL is unaffected -- this is the address Next dispatches to itself,
    // never anything a browser sees.
    target.protocol = "http:"
    const served = NextResponse.rewrite(target, { request: { headers: rewrittenHeaders } })
    served.headers.set(INTERNAL_REWRITE_HEADER, `${countryCode}`)
    if (!cacheIdCookie) {
      served.cookies.set("_medusa_cache_id", cacheId, { maxAge: 60 * 60 * 24 })
    }
    return served
  }

  // If no country code is set, we redirect to the relevant region.
  if (!urlHasCountryCode && countryCode) {
    response = redirectTo(
      `/${countryCode}${redirectPath}${queryString}`,
      PERMANENT_PREFIX_REDIRECT ? 308 : 307
    )
  } else if (!urlHasCountryCode && !countryCode) {
    // Handle case where no valid country code exists (empty regions)
    return new NextResponse(
      "No valid regions configured. Please set up regions with countries in your Medusa Admin.",
      { status: 500 }
    )
  }

  return response
}

export const config = {
  /**
   * ANCHOR THESE. The starter's list was bare prefixes, so any URL merely BEGINNING with one of
   * them skipped middleware entirely -- no legacy redirect, no bare-path rewrite, no cookie.
   *
   * `/giftcard` starts with `gif`. So did `/giftcards`, `/gift-cards` and `/giftshop`: all
   * returned 200 rendering an empty browse page, which is why the gift-card URL looked "linked
   * but blank" and why its redirect appeared to be ignored while `/GiftCard` -- different case,
   * no prefix match -- redirected correctly. `/apitest-xyz`, `/svg-anything`,
   * `/images-whatever` and `/assets-whatever` behaved the same way, while `/zzz-test-xyz`
   * honestly 404'd.
   *
   * Extensions now need a dot and an end-anchor; directories need their slash. Today only one
   * mapped URL was affected and no live product URL was -- but this is a landmine for any future
   * slug: a category called "gifts", a product named "Apiary", anything beginning with "png".
   */
  matcher: [
    "/((?!api/|_next/static|_next/image|favicon\\.ico|images/|assets/|.*\\.(?:png|svg|jpg|jpeg|gif|webp)$).*)",
  ],
}
